			{
				if(a==b)
				{
					if(matrix[a][b]!=1)
					{
						isIdentity=false;
						break;
					}
				}
				else
				{
					if(matrix[a][b]!=0)
					{
						isIdentity=false;
						break;
					}
				}
			}
			if(!isIdentity)
				break;
		}

		return isIdentity;
	}

