import java.io.File;
import java.io.FileNotFoundException;
import java.util.Scanner;

public class Renata {

	public static void main(String[] args) throws FileNotFoundException {
		Scanner data = new Scanner(new File("renata.dat"));
		int T = data.nextInt();
		for (int t = 1; t <= T; t++) {
			int N = data.nextInt();
			int [][] grid = new int[N+1][N+1];
			grid[0][0] = 0;
			for (int r = 1; r <= N; r++)
				for (int c = 1; c <= N; c++)
					grid[r][c] = data.nextInt();
			int shots = data.nextInt();
			int score = 0;
			for (int s = 1; s <= shots; s++)
				score += grid[data.nextInt()][data.nextInt()];
			System.out.printf("%d: %d\n", t, score);
		}
	}
}

import java.io.File;
import java.io.FileNotFoundException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.Scanner;

public class Sheal {

	public static void main(String[] args) throws FileNotFoundException
	{
		int[] fib = new int[21];
		fib[0] = fib[1] = 1;
		for(int i = 2;i<fib.length;i++)
			fib[i] = fib[i-1] + fib[i-2];
		Scanner file = new Scanner(new File("sheal.dat"));
		int T = file.nextInt();
		for(int casenum = 0;casenum<T;casenum++)
		{
			char[] options = file.next().toCharArray();
			int K = file.nextInt();
			HashSet<String> strs = new HashSet<String>();
			bruteForce(options, new boolean[options.length], "", strs);
			ArrayList<String> sorted = new ArrayList<String>();
			sorted.addAll(strs);
			Collections.sort(sorted);
			System.out.println(sorted.get(K));
		}
	}

	public static void bruteForce(char[] options, boolean[] used, String current, HashSet<String> strs)
	{
		strs.add(current);
		for(int i = 0;i<options.length;i++)
		{
			if(!used[i])
			{
				used[i] = true;
				bruteForce(options, used, current+options[i], strs);
				used[i] = false;
			}
		}
	}

}

